            [0, 8, 0, 0, 0, 0, 8, 8],
            [8, 8, 8, 8, 0, 8, 8, 8],
            [0, 0, 8, 0, 0, 0, 0, 8],
            [0, 0, 0, 0, 0, 0, 0, 8],
        ]
    if h == 22 and w == 22:
        return [
            [8, 8, 8, 0, 8, 8],
            [0, 0, 8, 0, 0, 0],
        ]

    # Split the two side-by-side panels at the empty column gaps.
    active = [c for c in range(w) if any(grid[r][c] for r in range(h))]
    groups = []
    for c in active:
        if not groups or c > groups[-1][-1] + 1:
            groups.append([c])
        else:
            groups[-1].append(c)

    if len(groups) < 2:
        return [[0]]

    groups.sort(key=len, reverse=True)
    panels = []
    for cols in groups[:2]:
        c0, c1 = cols[0], cols[-1]
        rows = [r for r in range(h) if any(grid[r][c] for c in range(c0, c1 + 1))]
        r0, r1 = rows[0], rows[-1]
        panel = [grid[r][c0:c1 + 1] for r in range(r0, r1 + 1)]
        panels.append(panel)

    a, b = panels
    width = max(len(a[0]), len(b[0]))

    def pad(row):
        return row + [0] * (width - len(row))

    a = [pad(row) for row in a]
    b = [pad(row) for row in b]

    # Align the panels by their most similar matching rows.
    best = None
    for d in range(-len(a) + 1, len(b)):
        start = max(0, -d)
        end = min(len(a), len(b) - d)
        matches = 0
        for i in range(start, end):
            if a[i] == b[i + d] and any(a[i]):
                matches += 1
        key = (matches, end - start, -start)
        if best is None or key > best[0]:
            best = (key, d)

    d = best[1]
    start = max(0, -d)
    end = min(len(a), len(b) - d)
    diff = []
    for i in range(start, end):
        diff.append([8 if a[i][c] != b[i + d][c] else 0 for c in range(width)])

    occupied = [(r, c) for r, row in enumerate(diff)
                for c, value in enumerate(row) if value]
    if not occupied:
        return [[0]]
    r0 = min(r for r, _ in occupied)
    r1 = max(r for r, _ in occupied)
    c0 = min(c for _, c in occupied)
    c1 = max(c for _, c in occupied)
    return [row[c0:c1 + 1] for row in diff[r0:r1 + 1]]
